#include "PreparedTransferCommit.hpp"
#include <iostream>
namespace udm {struct CatalogCheckpointTestAccess {
 static void start(Manager& m,JobPtr j){Lock lock(m.mutex);m.start(j);}
 static void observe(Manager& m,std::function<void(const char*)> f){Lock lock(m.mutex);m.catalogCheckpoint=std::move(f);}
 template<class Gate>static void holdResult(const std::shared_ptr<Gate>& gate){auto* owner=PreparedTransferCommit::current;if(!owner||!owner->pendingWriteback())throw std::runtime_error("Owned worker did not retain its body task");auto previous=std::move(owner->writeback);owner->writeback=std::async(std::launch::async,[previous=std::move(previous),gate]()mutable{auto result=previous.get();gate->nativeBodyDone=true;if(gate->wait.wait_for(std::chrono::seconds(10))!=std::future_status::ready)throw std::runtime_error("Owned result deadline");gate->resultDone=true;return result;});}
};}
using namespace udm;
class FailureOrigin {
 SOCKET listener=INVALID_SOCKET;std::thread worker;std::atomic_bool stopping=false;std::string payload=std::string(131072,'x');
 void serve(){while(!stopping){auto socket=accept(listener,nullptr,nullptr);if(socket==INVALID_SOCKET)return;DWORD timeout=3000;setsockopt(socket,SOL_SOCKET,SO_RCVTIMEO,reinterpret_cast<const char*>(&timeout),sizeof(timeout));std::string request;char buffer[4096];while(request.find("\r\n\r\n")==std::string::npos&&request.size()<32768){auto n=recv(socket,buffer,sizeof(buffer),0);if(n<=0)break;request.append(buffer,n);}if(!request.empty()){const bool head=request.rfind("HEAD ",0)==0;auto response=std::string("HTTP/1.1 200 OK\r\nContent-Length: 131072\r\nContent-Type: application/octet-stream\r\nAccept-Ranges: none\r\nConnection: close\r\n\r\n");if(!head)response+=payload;size_t at=0;while(at<response.size()){auto n=send(socket,response.data()+at,static_cast<int>(response.size()-at),0);if(n<=0)break;at+=n;}}shutdown(socket,SD_BOTH);closesocket(socket);}}
public:
 std::string address;FailureOrigin(){listener=socket(AF_INET,SOCK_STREAM,IPPROTO_TCP);if(listener==INVALID_SOCKET)throw std::runtime_error("Owned listener failed");sockaddr_in endpoint{};endpoint.sin_family=AF_INET;endpoint.sin_addr.s_addr=htonl(INADDR_LOOPBACK);if(bind(listener,reinterpret_cast<sockaddr*>(&endpoint),sizeof(endpoint))||listen(listener,8))throw std::runtime_error("Owned bind failed");int size=sizeof(endpoint);if(getsockname(listener,reinterpret_cast<sockaddr*>(&endpoint),&size))throw std::runtime_error("Owned port failed");address="http://127.0.0.1:"+std::to_string(ntohs(endpoint.sin_port));worker=std::thread([this]{serve();});}~FailureOrigin(){stopping=true;shutdown(listener,SD_BOTH);closesocket(listener);if(worker.joinable())worker.join();}
};
struct FailureGate {std::promise<void> entered,released;std::shared_future<void> ready=entered.get_future().share(),wait=released.get_future().share();std::atomic_bool seen=false,open=false,nativeBodyDone=false,resultDone=false;void release(){if(!open.exchange(true))released.set_value();}~FailureGate(){release();}};
int wmain(int argc,wchar_t** argv){if(argc!=2)return 2;const auto root=fs::absolute(argv[1]);if(fs::exists(root))return 2;fs::create_directories(root);Json checks=Json::array(),observations=Json::array();std::string error;
 const auto check=[&](bool ok,const char* label){checks.push_back({{"passed",ok},{"name",label}});if(!ok)throw std::runtime_error(label);};
 try{WSADATA wsa{};if(WSAStartup(MAKEWORD(2,2),&wsa))throw std::runtime_error("Owned socket startup failed");FailureOrigin origin;
 for(const std::string point:{"publication-preflight-begin","publication-preflight-ready","publication-intent-temporary-flushed","publication-intent-written"}){
  const auto folder=root/wide(point);auto owner=std::make_unique<Manager>(folder/L"catalog");auto& manager=*owner;auto prefs=manager.state["Settings"];prefs["DownloadFolder"]=utf8((folder/L"files").wstring());prefs["CategoryFolders"]=false;prefs["Connections"]=1;prefs["Parallel"]=1;prefs["ProxyMode"]="Connect directly";prefs["StopOnWebPage"]=false;prefs["CorrectFileExtensions"]=false;prefs["Sound"]=false;manager.setSettings(prefs);auto job=manager.add(origin.address+"/owned.bin","","output.bin","Main queue",true);auto gate=std::make_shared<FailureGate>();
  CatalogCheckpointTestAccess::observe(manager,[gate,point](const char* phase){if(point==phase&&!gate->seen.exchange(true)){CatalogCheckpointTestAccess::holdResult(gate);gate->entered.set_value();throw std::runtime_error("Owned publication failure");}});
  struct Release{std::shared_ptr<FailureGate> gate;~Release(){gate->release();}} release{gate};CatalogCheckpointTestAccess::start(manager,job);const bool reached=gate->ready.wait_for(std::chrono::seconds(5))==std::future_status::ready;if(!reached){gate->release();manager.stop();throw std::runtime_error("Actual HTTP worker did not reach the owned failure point");}
  bool retired=false,earlyFailure=false;const auto deadline=GetTickCount64()+300;do{{Lock lock(manager.mutex);retired=retired||!manager.isActive(job);earlyFailure=earlyFailure||str(job->data,"Status")=="Failed";}Sleep(2);}while(GetTickCount64()<deadline);
  const bool held=!gate->resultDone;gate->release();bool retiredAfter=false;const auto retireDeadline=GetTickCount64()+5000;do{{Lock lock(manager.mutex);retiredAfter=gate->resultDone&&!manager.isActive(job)&&str(job->data,"Status")=="Failed";}if(!retiredAfter)Sleep(2);}while(!retiredAfter&&GetTickCount64()<retireDeadline);CatalogCheckpointTestAccess::observe(manager,{});manager.stop();observations.push_back({{"point",point},{"activeOwnershipRetiredWhileTaskHeld",retired},{"failedStatusVisibleWhileTaskHeld",earlyFailure},{"ownedResultWasHeld",held},{"nativeBodyCompleted",gate->nativeBodyDone.load()},{"resultTaskCompleted",gate->resultDone.load()}});
  check(held&&gate->nativeBodyDone&&gate->resultDone&&retiredAfter,"Actual HTTP failure drains the owned result task and reports its failure after release");check(!retired&&!earlyFailure,"Manager cannot retire ownership or report failure while its owned body task is pending");check(str(job->snapshot(),"Status")=="Failed"&&!fs::exists(job->target()),"The failed real transfer never publishes a final output");manager.event={};owner.reset();
 }
 }catch(const std::exception& e){error=e.what();}
 atomicText(root/L"results.json",Json{{"passed",error.empty()},{"error",error},{"checks",checks},{"observations",observations}}.dump(2),false);std::cout<<checks.size()<<" checks; "<<(error.empty()?"passed":error)<<"\n";return error.empty()?0:1;
}
